custom_css:
/* ============================================================
   THE LIBRARY OF BABEL — тема для Tavo по рассказу Борхеса
   Ответы персонажа — печатные страницы с буквицей,
   ваши сообщения — пометки на полях от руки.
   Пока персонаж отвечает, в поле ввода бегут случайные книги:
   библиотекарь ищет ту самую среди всех возможных.
   Шрифт EB Garamond (SIL OFL 1.1) встроен в тему.
   Нужен Advanced Rendering.
   ============================================================ */

@font-face {
  font-family: "EB Garamond";
  font-style: normal;
  font-weight: 400 700;
  font-display: swap;
  src: url("theme/assets/ebgaramond-cyrillic.woff2") format("woff2");
  unicode-range: U+0301, U+0400-045F, U+0490-0491, U+04B0-04B1, U+2116;
}
@font-face {
  font-family: "EB Garamond";
  font-style: normal;
  font-weight: 400 700;
  font-display: swap;
  src: url("theme/assets/ebgaramond-latin.woff2") format("woff2");
  unicode-range: U+0000-00FF, U+0131, U+0152-0153, U+02BB-02BC, U+02C6, U+02DA, U+02DC, U+0304, U+0308, U+0329, U+2000-206F, U+20AC, U+2122, U+2191, U+2193, U+2212, U+2215, U+FEFF, U+FFFD;
}
@font-face {
  font-family: "EB Garamond";
  font-style: italic;
  font-weight: 400 700;
  font-display: swap;
  src: url("theme/assets/ebgaramond-italic-cyrillic.woff2") format("woff2");
  unicode-range: U+0301, U+0400-045F, U+0490-0491, U+04B0-04B1, U+2116;
}
@font-face {
  font-family: "EB Garamond";
  font-style: italic;
  font-weight: 400 700;
  font-display: swap;
  src: url("theme/assets/ebgaramond-italic-latin.woff2") format("woff2");
  unicode-range: U+0000-00FF, U+0131, U+0152-0153, U+02BB-02BC, U+02C6, U+02DA, U+02DC, U+0304, U+0308, U+0329, U+2000-206F, U+20AC, U+2122, U+2191, U+2193, U+2212, U+2215, U+FEFF, U+FFFD;
}

/* ---------- Анимации ---------- */

/* Неровное дыхание пламени лампы над столом */
@keyframes babel-lamp {
  0%   { box-shadow: 0 0 0 1px rgba(201, 166, 107, 0.4), 0 -6px 22px rgba(255, 206, 140, 0.16), 0 8px 18px rgba(0, 0, 0, 0.6); }
  17%  { box-shadow: 0 0 0 1px rgba(201, 166, 107, 0.45), 0 -6px 26px rgba(255, 206, 140, 0.22), 0 8px 18px rgba(0, 0, 0, 0.6); }
  31%  { box-shadow: 0 0 0 1px rgba(201, 166, 107, 0.38), 0 -6px 18px rgba(255, 206, 140, 0.12), 0 8px 18px rgba(0, 0, 0, 0.6); }
  58%  { box-shadow: 0 0 0 1px rgba(201, 166, 107, 0.46), 0 -6px 28px rgba(255, 206, 140, 0.24), 0 8px 18px rgba(0, 0, 0, 0.6); }
  76%  { box-shadow: 0 0 0 1px rgba(201, 166, 107, 0.4), 0 -6px 20px rgba(255, 206, 140, 0.15), 0 8px 18px rgba(0, 0, 0, 0.6); }
  100% { box-shadow: 0 0 0 1px rgba(201, 166, 107, 0.4), 0 -6px 22px rgba(255, 206, 140, 0.16), 0 8px 18px rgba(0, 0, 0, 0.6); }
}

/* Поиск: две полосы случайных книг текут навстречу друг другу */
@keyframes babel-search {
  0%   { background-position: 0 4px, 0 calc(100% - 3px), 0 0; }
  100% { background-position: calc(-1 * 576px) 4px, 546px calc(100% - 3px), 0 0; }
}

/* ---------- Общая типографика ---------- */
.tavo-bubble-content,
.tavo-speaker-name,
.tavo-composer-input {
  font-family: "EB Garamond", "Noto Serif", Georgia, serif;
}

.tavo-message-content {
  line-height: 1.62;
  hyphens: auto;
}

.tavo-message-content::selection,
.tavo-message-content *::selection {
  background: rgba(201, 166, 107, 0.45);
  color: inherit;
}

/* ---------- Персонаж: страница из книги ---------- */
.tavo-bubble {
  border-radius: 2px;
}

.tavo-character-bubble {
  background-color: #efe3c8;
  background-image:
    url("theme/assets/hex-mark.svg"),
    url("theme/assets/paper.png");
  background-size: 54px 22px, 256px 256px;
  background-repeat: no-repeat, repeat;
  background-position: center bottom 6px, 0 0;
  padding-bottom: 30px;
  box-shadow:
    inset 0 0 24px rgba(120, 84, 40, 0.38),
    inset 0 0 2px rgba(120, 84, 40, 0.5),
    0 8px 20px rgba(0, 0, 0, 0.55);
}

/* Буквица в начале каждого ответа */
.tavo-character-bubble-content .tavo-message-content::first-letter {
  float: left;
  font-family: "EB Garamond", Georgia, serif;
  font-size: 3.05em;
  line-height: 0.82;
  font-weight: 600;
  color: #7a2a1e;
  padding: 0.08em 0.08em 0 0;
  text-shadow: 0.5px 0.5px 0 rgba(201, 166, 107, 0.6);
}

/* ---------- Вы: пометки на полях ---------- */
.tavo-user-bubble {
  background-color: rgba(18, 13, 8, 0.6);
  border-left: 1px solid rgba(201, 166, 107, 0.7);
  box-shadow: inset 3px 0 0 -2px rgba(201, 166, 107, 0.35);
}

.tavo-user-bubble-content {
  font-style: italic;
}

/* ---------- Имена и аватары-камеи ---------- */
.tavo-speaker-name {
  font-variant: small-caps;
  letter-spacing: 0.12em;
  color: #c9a66b;
  font-size: 1.05em;
}

.tavo-avatar {
  outline: 1.5px solid rgba(201, 166, 107, 0.85);
  outline-offset: -1.5px;
  filter: sepia(0.55) contrast(1.05) brightness(0.95);
}

/* ---------- Рассуждения: глосса на полях ---------- */
.tavo-message-reasoning {
  font-style: italic;
  font-size: 0.92em;
  border-left: 1px dotted rgba(122, 42, 30, 0.6);
  padding-left: 10px;
  opacity: 0.85;
}

.tavo-message-reasoning > summary::before {
  content: "¶ ";
  color: #7a2a1e;
  font-style: normal;
}

.tavo-message-divider {
  height: 28px;
  border: 0;
  background: url("theme/assets/divider.svg") center / min(320px, 76%) auto no-repeat;
}

.tavo-message-attachments {
  filter: sepia(0.35);
  box-shadow: 0 0 0 4px #efe3c8, 0 6px 16px rgba(0, 0, 0, 0.5);
}

.tavo-action-bar-button,
.tavo-action-bar-button-group {
  background-color: rgba(18, 13, 8, 0.75);
  border-radius: 2px;
}

/* ---------- Поле ввода: стол читателя под лампой ---------- */
.tavo-composer-shell {
  background-color: rgba(30, 21, 13, 0.94);
  background-image: linear-gradient(180deg, rgba(255, 206, 140, 0.07), rgba(0, 0, 0, 0) 60%);
  border-radius: 6px;
  border: 0;
  animation: babel-lamp 7s ease-in-out infinite;
}

/* Пока персонаж отвечает — поиск среди всех возможных книг */
:root:has(.tavo-composer-stop-icon) .tavo-composer-shell {
  background-image:
    url("theme/assets/glyphs-a.png"),
    url("theme/assets/glyphs-b.png"),
    linear-gradient(180deg, rgba(255, 206, 140, 0.1), rgba(0, 0, 0, 0) 60%);
  background-size: 576px 15px, 546px 13px, auto;
  background-repeat: repeat-x, repeat-x, no-repeat;
  animation:
    babel-lamp 2.4s ease-in-out infinite,
    babel-search 38s linear infinite;
}

.tavo-composer-input {
  color: #e8d9b8;
  caret-color: #c9a66b;
}

.tavo-composer-input::placeholder {
  color: #8a7656;
  font-style: italic;
}

.tavo-composer-send-icon,
.tavo-composer-add-icon,
.tavo-composer-voice-icon,
.tavo-composer-stop-icon {
  filter: sepia(1) saturate(1.4) brightness(0.95);
}

@media (prefers-reduced-motion: reduce) {
  .tavo-composer-shell,
  :root:has(.tavo-composer-stop-icon) .tavo-composer-shell {
    animation: none;
  }
}
